  \rowcolor{tablebg}
  2 & NousResearch/hermes-agent & Python & 468 & 102 & 66 & 61 & \colorbox{aigreen}{\fontsize{18}{22}\selectfont\color{aitag}\textbf{\,AI\,}} \\
  \rowcolor{rowhover}
