  \rowcolor{rowhover}
  5 & VoltAgent/awesome-design-md & HTML & 321 & 49 & 0 & 0 & \colorbox{aigreen}{\fontsize{18}{22}\selectfont\color{aitag}\textbf{\,AI\,}} \\
  \rowcolor{tablebg}
